'use strict';
/* The default map must never promote rainfall or a planning scenario to current flooding. */
const currentOption=document.createElement('option');currentOption.value='current';currentOption.textContent='Situação atual · inundação calculada';$('view').prepend(currentOption);$('view').value='current';
for(let option of [...$('view').options])if(['pressure','priority'].includes(option.value))option.remove();
const scenarioOption=$('view').querySelector('[value=scenario]');scenarioOption.textContent='Consultar cenários APA · planeamento';
document.querySelector('.notice').innerHTML='<b>Inundação atual: ainda sem cálculo hidráulico validado</b><p>Chuva e escoamento estão a ser calculados. Uma freguesia só será sinalizada nesta vista quando uma mancha hidráulica datada, com nível e ligação ao rio, a atingir. Não se assume risco zero.</p>';
document.querySelector('.section-title h2').textContent='Consultar freguesias';
document.querySelector('.section-title').nextElementSibling.textContent='Na vista atual, não há classificação sem mancha hidráulica calculada. Os cenários APA são uma consulta separada.';
const renderBeforeGate=render;render=function(){renderBeforeGate();let current=$('view').value==='current';$('period').parentElement.hidden=current;document.querySelector('[data-layer=risk]').disabled=current;document.querySelector('[data-layer=risk]').parentElement.hidden=current;if(map?.getLayer('risk')){map.setLayoutProperty('risk','visibility',current?'none':document.querySelector('[data-layer=risk]').checked?'visible':'none');map.setPaintProperty('parishes-fill','fill-opacity',current?.05:.32);}if(current){$('legend').innerHTML='<b>Situação atual</b><div class="legend-row"><i class="swatch" style="background:#168ec0"></i>Rios · rede normal</div><div class="legend-row"><i class="swatch" style="background:#9aa9ad"></i>Freguesias · avaliação hidráulica pendente</div><small>A chuva acumulada não basta para determinar o nível que atinge uma freguesia. Sem mancha calculada, nenhuma freguesia é sinalizada como inundada.</small>';document.querySelectorAll('.result .badge').forEach(b=>{b.textContent='Por avaliar';b.style.background='#eef3f4';});}if(map?.getLayer('rivers')){map.setPaintProperty('rivers','line-color','#168ec0');map.setPaintProperty('rivers','line-width',1.5);}document.querySelector('.map-note').textContent=current?'Atual: sem mancha hidráulica validada · dados em falta não significam risco zero':'Cenário APA T'+period+' · não é cheia em curso';};
const hydrologyShow=showParish;let histories=new Map();
showParish=function(code,fly=true){hydrologyShow(code,fly);let f=data.parishes.features.find(f=>f.properties.dtmnfr===code),p=f?.properties;if(!p)return;let b=p.basin_ids.map(id=>simulations.get(id)).filter(Boolean).sort((a,b)=>(b.p24_mm??-1)-(a.p24_mm??-1))[0],hist=b?histories.get(b.id):null;let root=$('detail-content');if($('view').value==='current'){let pressure=[...root.querySelectorAll('h3')].find(h=>h.textContent==='Pressão meteorológica nas bacias');if(pressure){let n=pressure.nextElementSibling;while(n&&n.tagName!=='H3'){let next=n.nextElementSibling;n.remove();n=next;}pressure.remove();}if($('exposure-button'))$('exposure-button').hidden=true;let tag=root.querySelector('.badge');if(tag){tag.textContent='Situação atual: avaliação hidráulica pendente';tag.style.background='#eef3f4';}let title=root.querySelector('h3');if(title){title.textContent='Inundação atual';let paragraph=title.nextElementSibling?.nextElementSibling;if(paragraph?.tagName==='P')paragraph.textContent='Ainda não existe uma mancha hidráulica atual validada que permita determinar se a água atinge esta freguesia. Consulte os cenários APA apenas na vista de planeamento.';}}
if(b){root.insertAdjacentHTML('beforeend','<h3>Chuva e escoamento · bacia #'+b.id+'</h3><p><b>'+E(b.modelled_rainfall?'Estimativa meteorológica ECMWF':'Observações IPMA')+'</b> · válido '+date(b.valid_time)+'</p><dl>'+metric('Chuva acumulada 24 h',num(b.p24_mm)+' mm')+metric('Volume precipitado',num(b.rainfall_volume_m3/1e6,3)+' hm³')+b.runoff_sensitivity.map(r=>metric('Volume escoado · CN'+r.cn,num(r.volume_m3/1e6,3)+' hm³')).join('')+metric('Nível atingido na freguesia','Por calcular')+'</dl><p>O volume é calculado na área da bacia. Sem propagação, secções, cotas e operação das barragens não é convertido em altura nem em área inundada.</p>');}
if(hist){let years=hist.annual.map(y=>y.max_daily_mm),max=Math.max(...years);root.insertAdjacentHTML('beforeend','<h3>Estudo estimado · 2016–2025</h3><p>ERA5, 28 referências regionais com interpolação IDW3. '+hist.n_days+' dias completos; referência espacial aproximada, não estação local.</p><dl>'+metric('Precipitação anual média',num(hist.annual_mean_mm)+' mm')+metric('P95 diário',num(hist.daily_p95_mm)+' mm')+metric('P99 diário',num(hist.daily_p99_mm)+' mm')+metric('Maior dia nos dez anos',num(hist.max_daily_mm)+' mm')+'</dl><div class="chart">'+hist.annual.map(y=>'<div title="'+y.year+': '+num(y.max_daily_mm)+' mm" style="height:'+Math.max(2,y.max_daily_mm/max*100)+'%"></div>').join('')+'</div><p>Máximos diários anuais, 2016 → 2025. Não são níveis nem caudais de cheia.</p>');}
};
async function loadStudies(){let [history,simulation,t10,bulletin]=await Promise.all([get('history.json'),get('simulation.json'),get('t10.json'),get('reservoir-bulletin.json')]);histories=new Map(history.basins.map(b=>[b.id,b]));simulations.clear();for(let b of simulation.basins)simulations.set(b.id,b);data.bulletin=bulletin;let info=document.createElement('div');info.className='notice';info.innerHTML='<b>Estudo estimado · 2016–2025</b><p>262 bacias · 28 referências ERA5 · 3 653 dias por referência. Estimativas ECMWF completam as bacias sem estações suficientes.</p><button id="study-button">Ver resultados e cálculo T10</button>';document.querySelector('.source-footer').before(info);$('study-button').onclick=()=>{$('method-content').innerHTML='<h2>Resultados estimados · dez anos</h2><p>Referência ERA5 de 2016 a 2025, 28 pontos regionais. Interpolação para 262 bacias. Os valores de chuva são estimativas de modelo; o escoamento é sensibilidade SCS-CN, sem calibração.</p><h3>T10 de caudal diário · estudo preliminar</h3><p>GloFAS via Open-Meteo, dez máximos anuais 2016–2025, ajuste Gumbel por momentos e bootstrap. As células do modelo não estão validadas contra os troços locais. Estes limiares não acionam cores de risco na freguesia.</p><table><tr><th>Referência</th><th>Q10 diário estimado</th><th>Intervalo bootstrap 95%</th></tr>'+t10.stations.map(s=>'<tr><td>'+E(s.name)+'</td><td>'+(/RÉGUA/.test(s.name)?'Excluído: célula não representativa':num(s.q10_gumbel_moments_m3s)+' m³/s')+'</td><td>'+(/RÉGUA/.test(s.name)?'Por rever':s.bootstrap95_m3s.map(x=>num(x)).join('–')+' m³/s')+'</td></tr>').join('')+'</table><p>T10 corresponde a 10% de probabilidade anual de excedência no modelo ajustado. O caudal médio diário não é o pico instantâneo. Não determina a cota nem a mancha que atinge as freguesias. Dez anos são uma amostra curta e não sustentam T100/T1000.</p><h3>Barragens: boletins disponíveis</h3><p>'+bulletin.records.length+' registos. SNIRH mensal '+E(bulletin.monthly_reference)+'; ARBCAS com data diária. Não há descargas/afluências contínuas assimiladas.</p><p><a href="report.html">Relatório completo com figuras ↗</a></p>';$('method').showModal();};render();}
const studiesReady=setInterval(()=>{if(data.parishes&&map&&map.getLayer('rivers')){clearInterval(studiesReady);loadStudies().catch(e=>console.warn('Estudo: '+e.message));}},250);
